```sql
create table organizations (id uuid primary key, name text not null);
create table teams (id uuid primary key, org_id uuid not null references organizations(id));
create table users (id uuid primary key, email citext unique not null);
create table memberships (user_id uuid references users(id), team_id uuid references teams(id), primary key(user_id, team_id));

create table roles (id uuid primary key, key text unique not null);
create table permissions (id uuid primary key, key text unique not null);
create table role_permissions (role_id uuid references roles(id), perm_id uuid references permissions(id), primary key(role_id, perm_id));

-- subject_type: 'org' | 'team' | 'user' ; scope_type: e.g., 'project'
create table grants (
  id uuid primary key,
  subject_type text not null, subject_id uuid not null,
  role_id uuid not null references roles(id),
  scope_type text, scope_id uuid,
  org_id uuid not null references organizations(id),
  created_at timestamptz not null default now()
);

create table resources (
  id uuid primary key,
  type text not null,
  owner_org uuid not null references organizations(id)
);

create table resource_acl (
  resource_id uuid references resources(id),
  subject_type text not null, subject_id uuid not null,
  perm_key text not null,
  effect text not null check (effect in ('allow','deny')),
  primary key(resource_id, subject_type, subject_id, perm_key)
);
```
