Server‑deterministic experiments via cookie so SSR and CSR match:\n\n```ts
// middleware.ts
import { NextResponse } from 'next/server'
import type { NextRequest } from 'next/server'

export function middleware(req: NextRequest) {
  const res = NextResponse.next()
  let v = req.cookies.get('exp_home')?.value
  if (!v) {
    const key = req.headers.get('x-user-id') || req.ip || 'anon'
    const hash = Array.from(key).reduce((h, c) => (h * 31 + c.charCodeAt(0)) >>> 0, 0)
    v = hash % 2 === 0 ? 'A' : 'B'
    res.cookies.set('exp_home', v, { path: '/', httpOnly: false, sameSite: 'Lax' })
  }
  res.headers.set('x-exp-home', v)
  return res
}
```

