Online migration with SQL (expand→contract):\n\n```sql
-- 1) Expand: add nullable column without default (no table rewrite)
alter table orders add column processed_at timestamptz;

-- 2) Backfill in throttled batches (run repeatedly)
update orders
set processed_at = created_at
where processed_at is null
order by id
limit 10000;

-- Optional trigger for dual‑write safety
create or replace function set_processed_at() returns trigger as $$
begin
  if NEW.processed and NEW.processed_at is null then
    NEW.processed_at := now();
  end if;
  return NEW;
end;
$$ language plpgsql;

create trigger ensure_processed_at
before insert or update on orders
for each row execute procedure set_processed_at();

-- 3) Contract: enforce NOT NULL after backfill completes
alter table orders alter column processed_at set not null;
```
\nApply with a psql loop between batches:\n```sh
for i in $(seq 1 200); do psql -c 'update orders set processed_at=created_at where processed_at is null limit 10000'; sleep 0.1; done
```

Add a guarded code path before flipping reads:\n\n```ts
// orders.service.ts
async function createOrder(input: NewOrder) {
  const now = new Date()
  await db.tx(async (t) => {
    await t.none('insert into orders(id, processed, created_at, processed_at) values($1,$2,$3,$4)', [
      input.id,
      input.processed,
      now,
      input.processed ? now : null,
    ])
  })
}
```
Then switch reads to `processed_at` only after backfill completes and NOT NULL is enforced.

