Evaluation + rollout config:\n\n```ts
// eval.ts
import murmurhash from 'murmurhash'

export type Rule = { if: Record<string, string | number | boolean>, pct?: number }
export type Flag = { key: string, on: boolean, rules: Rule[], fallthroughPct?: number }

export function isEnabled(flag: Flag, attrs: Record<string, any>): boolean {
  if (!flag.on) return false
  for (const r of flag.rules) {
    const match = Object.entries(r.if).every(([k,v]) => attrs[k] === v)
    if (match) return bucket(flag.key, attrs.userId) < (r.pct ?? 100)
  }
  return bucket(flag.key, attrs.userId) < (flag.fallthroughPct ?? 0)
}

function bucket(key: string, userId: string): number {
  const n = murmurhash.v3(`${key}:${userId}`) % 100
  return n
}
```

