// limiter.ts (Redis token bucket)
import { createClient } from 'redis'
const r = createClient()
export async function allow(key: string, rate=10, perSec=1) {
  const now = Math.floor(Date.now()/1000)
  const bucket = `tb:${key}:${now}`
  const n = await r.incr(bucket)
  if (n === 1) await r.expire(bucket, perSec)
  return n <= rate
}
```

