import express from 'express'
import {
  generateRegistrationOptions,
  verifyRegistrationResponse
} from '@simplewebauthn/server'

const app = express()
app.use(express.json())

app.get('/webauthn/reg/options', (req, res) => {
  const opts = generateRegistrationOptions({ rpName: 'Acme', userID: req.user.id })
  req.session.challenge = opts.challenge
  res.json(opts)
})

app.post('/webauthn/reg/verify', async (req, res) => {
  const verification = await verifyRegistrationResponse({
    response: req.body,
    expectedChallenge: req.session.challenge,
    expectedOrigin: 'https://app.example.com',
    expectedRPID: 'example.com'
  })
  // store credential
  res.json({ ok: verification.verified })
})
```

