Ingest (Node) + DP (Python) + TTL (SQL):\n\n```ts
// ingest.ts
import express from 'express'
import crypto from 'crypto'
const app = express(); app.use(express.json())
function pseudonymize(userId: string) {
  return crypto.createHmac('sha256', process.env.SALT!).update(userId).digest('hex')
}
app.post('/collect', async (req, res) => {
  const { userId, consent, ...ev } = req.body
  if (!consent) return res.status(204).end()
  const user_id_hash = userId ? pseudonymize(userId) : undefined
  const record = { ...ev, user_id_hash, ts: new Date().toISOString() }
  // enqueue to Kafka/SQS
  await queue.send(record)
  res.status(202).end()
})
```

