```js
// scripts/shard.js
const fs = require('fs')
const shard = parseInt(process.argv[2]); const total = parseInt(process.argv[3])
const times = JSON.parse(fs.readFileSync('timings.json','utf-8')) // { file: ms }
const files = Object.entries(times).sort((a,b)=>b[1]-a[1]).map(([f])=>f)
const buckets = Array.from({length: total}, ()=>({t:0, files:[]}))
for (const f of files) {
  buckets.sort((a,b)=>a.t-b.t)
  const b = buckets[0]
  b.files.push(f); b.t += times[f] || 1000
}
console.log(buckets[shard].files.join(' '))
```

