// archiver.js (Node)
import { MongoClient } from 'mongodb'
const src = new MongoClient(process.env.MONGO_SRC!)
const dst = new MongoClient(process.env.MONGO_COLD!)
await src.connect(); await dst.connect()
const s = src.db('prod').collection('events')
const d = dst.db('archive').collection('events')
const cutoff = new Date(Date.now() - 25*24*3600*1000)
const cur = s.find({ expiresAt: { $lt: cutoff } }, { batchSize: 1000 })
for await (const doc of cur) {
  await d.insertOne(doc)
  await s.deleteOne({ _id: doc._id })
}
