Apollo Server plugin + Redis limiter:\n\n```ts
import { createComplexityRule } from 'graphql-validation-complexity'
import { Redis } from 'ioredis'

const redis = new Redis(process.env.REDIS_URL!)

function bucketKey(tenant: string) { return `gql:${tenant}:${Math.floor(Date.now()/1000)}` }
async function allow(tenant: string, limit=100, perSec=1) {
  const k = bucketKey(tenant)
  const n = await redis.incr(k)
  if (n === 1) await redis.expire(k, perSec)
  return n <= limit
}

const costMap: Record<string, number> = { Query__search: 5, Query__me: 1 }

export const complexityRule = createComplexityRule({
  maximumComplexity: 100,
  variables: {},
  createError: (max, actual) => new Error(`Complexity ${actual}/${max}`),
  estimators: [
    ({ typeName, fieldName }) => costMap[`${typeName}__${fieldName}`] ?? 1
  ]
})

export const rateLimitPlugin = {
  async requestDidStart(ctx) {
    const tenant = ctx.request.http?.headers.get('x-tenant') || 'anon'
    if (!(await allow(tenant))) throw new Error('rate limit exceeded')
    return {}
  }
}
```

