import { z } from 'zod'

export const Event = z.object({
  type: z.string(),
  ts: z.string(),
  userId: z.string().optional(),
  anonId: z.string().optional(),
  props: z.record(z.any()).default({})
}).refine(e => !!(e.userId || e.anonId), { message: 'userId or anonId required' })

export async function track(ev: z.infer<typeof Event>) {
  const parsed = Event.parse(ev)
  await fetch('/collect', {
    method: 'POST', headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify(parsed)
  })
}
