Presign + AV worker:\n\n```ts
// presign.ts (@aws-sdk v3)
import { S3Client, PutObjectCommand } from '@aws-sdk/client-s3'
import { getSignedUrl } from '@aws-sdk/s3-request-presigner'
const s3 = new S3Client({})
export async function presign(key: string, type: string) {
  const cmd = new PutObjectCommand({ Bucket: process.env.BUCKET!, Key: key, ContentType: type })
  return await getSignedUrl(s3, cmd, { expiresIn: 300 })
}
```

```ts
// worker.ts (scan and move)
import { S3Client, GetObjectCommand, CopyObjectCommand, DeleteObjectCommand } from '@aws-sdk/client-s3'
import net from 'net'

async function clamScan(buf: Buffer) {
  return new Promise<boolean>((resolve, reject) => {
    const socket = net.createConnection(3310, 'clamav', () => {
      socket.write(Buffer.concat([Buffer.from('zINSTREAM\n'), buf, Buffer.from([0,0,0,0])]))
    })
    socket.on('data', d => resolve(!d.toString().includes('FOUND')))
    socket.on('error', reject)
  })
}

const s3 = new S3Client({})
export async function handle(key: string) {
  const obj = await s3.send(new GetObjectCommand({ Bucket: process.env.QUARANTINE!, Key: key }))
  const buf = Buffer.from(await obj.Body!.transformToByteArray())
  const clean = await clamScan(buf)
  if (!clean) return // quarantine retained
  await s3.send(new CopyObjectCommand({ Bucket: process.env.BUCKET!, CopySource: `${process.env.QUARANTINE}/${key}`, Key: key }))
  await s3.send(new DeleteObjectCommand({ Bucket: process.env.QUARANTINE!, Key: key }))
}
```

