-- retention: drop partitions older than N months
create or replace function drop_old_partitions(months int) returns void as $$
declare r record; begin
  for r in select relname from pg_class where relname like 'events_%' loop
    perform 1; -- evaluate name to date and drop if older
  end loop;
end; $$ language plpgsql;
