import { Worker } from 'worker_threads'
const pool: Worker[] = []
for (let i=0;i<4;i++) pool.push(new Worker('./cpu.js'))
let next = 0
export function runJob(payload: any) {
  return new Promise((res) => {
    const w = pool[next]; next = (next+1)%pool.length
    w.once('message', res); w.postMessage(payload)
  })
}
