app.get('/download', async (req,res) => {
  const { token } = req.query
  const { sub, key } = verify(String(token)) as any
  const used = await r.get(`dl:${token}`)
  if (used) return res.status(410).end()
  await r.setEx(`dl:${token}`, 3600, '1')
  const stream = await s3.getObject({ Bucket: B, Key: key })
  stream.createReadStream().pipe(res)
})
