Client reconnect:\n\n```ts
function connect() {
  let attempt = 0, ws: WebSocket
  const url = 'wss://example.com/ws'
  const go = () => {
    ws = new WebSocket(url)
    ws.onopen = () => { attempt = 0 }
    ws.onclose = () => {
      attempt++
      const backoff = Math.min(2**attempt * 250, 8000) + Math.floor(Math.random()*250)
      setTimeout(go, backoff)
    }
  }
  go()
}
```

