const tracer = trace.getTracer('app')

// producer
const span = tracer.startSpan('kafka.produce')
const headers = {}
propagation.inject(context.active(), headers)
producer.send({ topic: 'orders', messages: [{ value: JSON.stringify(ev), headers }] })
span.end()

// consumer
await consumer.run({ eachMessage: async ({ message }) => {
  const ctx = propagation.extract(context.active(), message.headers as any)
  await context.with(ctx, async () => {
    const span = tracer.startSpan('kafka.consume')
    // handle
    span.end()
  })
})
