app.post('/webhook', express.raw({ type: '*/*' }), (req,res) => {
  const sig = req.get('x-signature')!
  const mac = crypto.createHmac('sha256', process.env.SECRET!).update(req.body).digest('hex')
  if (!timingSafeEqual(Buffer.from(sig,'hex'), Buffer.from(mac,'hex'))) return res.status(401).end()
  handle(JSON.parse(req.body.toString())); res.status(204).end()
})
