Go breaker:\n\n```go
type Breaker struct{ fails, total int; open bool; openedAt time.Time }
func (b *Breaker) Allow() bool { if b.open && time.Since(b.openedAt) < time.Second*5 { return false }; return true }
func (b *Breaker) OnResult(err error){ b.total++; if err != nil { b.fails++ }; if b.total>=20 && float64(b.fails)/float64(b.total) > 0.5 { b.open=true; b.openedAt=time.Now(); b.fails,b.total=0,0 } }
```

